matureCountry("venezuela",{
  lead:"Venezuela is an American-dominated security republic created by the 1966 intervention and the postwar order the archive calls the Caracas settlement. Spanish, Italian, and broader Latin institutions remain culturally and commercially important, but they operate beneath an American strategic ceiling that excludes rival bases, defense control, and foreign command of petroleum infrastructure.",
  canon:"The intervention, conditional sovereignty, and firm American domination remain established. Later Latin banking, media, construction, Catholic, consumer, and immigration networks are established as a secondary layer rather than an alternative alignment. Detailed portfolios remain open.",
  sections:[{id:"mature-layer",title:"American ceiling and Latin layer after 1985",html:"<p>By 2000 Venezuela is not an American–Latin geopolitical battleground. Washington's advisers, facilities, oil-security rights, and intervention legacy settle the strategic question. Spanish and Italian firms may prosper in banking, construction, media, consumer markets, and Catholic networks, but cannot convert commerce into a rival naval position or control of petroleum infrastructure.</p>"}],
  related:[{href:"caracas.html",kicker:"Capital",label:"Caracas"},{href:"corporate-geopolitics-americas.html",kicker:"Layered comparison",label:"Corporate Geopolitics in the Americas"}],
  facts:[["Capital","Caracas"],["Strategic position by 2000","Firm American client"],["Practical sovereignty","Conditional under the post-1966 security order"],["Archive settlement label","Caracas settlement; formal title open"],["Secondary cultural-commercial layer","Spanish, Italian, and broader Latin"],["Excluded rival control","Defense, bases, and petroleum infrastructure"]]
});

matureCountry("cuba",{
  lead:"Cuba develops from an independent fortress state into a sovereign, Latin-affiliated island that deliberately invites Spanish and broader Latin capital while keeping American corporations at a distance. Its economic opening is presented in Havana as an act of resistance to American integration, not reconciliation with Washington.",
  canon:"The fortress system and Havana Understanding remain established. The later selective opening, severe suspicion of American firms, Spanish and Latin preference, and Latin affiliation by 2000 are fixed at framework level; dates, companies, and laws remain open.",
  sections:[{id:"latin-opening",title:"The Latin opening",html:"<p>Economic need eventually required foreign banking, shipping, tourism, industrial equipment, telecommunications, and insurance. Havana invited Spanish and other Latin institutions specifically to avoid solving those needs through American corporations. The resulting <a href='cuban-latin-opening.html'>opening</a> made Cuba the Latin-affiliated exception inside an American Caribbean.</p>"}],
  related:[{href:"havana.html",kicker:"Capital",label:"Havana"},{href:"cuban-latin-opening.html",kicker:"Post-fortress economy",label:"Cuban Opening to the Latin World"}],
  facts:[["Capital","Havana"],["1985 doctrine","Fortress / porcupine defense"],["Position by 2000","Sovereign and Latin-affiliated"],["Preferred external firms","Spanish and broader Latin"],["American corporate role","Restricted and distrusted"]]
});

matureCountry("mexico",{
  lead:"Mexico is the hemisphere's largest independent northern balancer. By 2000 its politics show stronger Catholic-corporatist and Spanish influence, while its economy remains Mexican-first, deliberately plural, and deeply penetrated by American trade and investment that geography makes impossible to exclude.",
  canon:"The Second Cristiada settlement, enduring independence, Mexican-first corporate hierarchy, Latin counterweight, large American presence, and sovereign gold-defined currency are established. Claims that Mexico formally enters the Latin bloc remain sensationalist rather than canon; currency name, parity, and detailed post-1985 governments remain open.",
  sections:[{id:"plural-economy",title:"Mexican-first corporate plurality",html:"<p>Policy prefers a viable Mexican firm, then a Spanish or other Latin supplier where an external counterweight is desired, and accepts American firms where border supply chains, price, technology, or investment prevail. The result is an economic contest among sponsors rather than a military alignment contest.</p>"},{id:"gold-currency",title:"Gold-defined national currency",html:"<p>Mexico adopts its own <a href='mexican-gold-currency.html'>gold-defined sovereign currency</a> to settle readily with both dollar and scudo. It achieves monetary sovereignty without dollarization, scudo membership, or isolation.</p>"}],
  related:[{href:"mexico-city.html",kicker:"Capital",label:"Mexico City"},{href:"mexican-gold-currency.html",kicker:"Monetary bridge",label:"Mexican Gold Currency"},{href:"corporate-geopolitics-americas.html",kicker:"Regional setting",label:"Corporate Geopolitics in the Americas"}],
  facts:[["Capital","Mexico City"],["Strategic position by 2000","Independent"],["Political tendency","Catholic-corporatist and Spanish-influenced"],["Corporate order","Mexican-first, Latin counterweight, major American presence"],["Currency","Sovereign gold-defined national money"],["Formal Latin-bloc membership","None"]]
});

matureCountry("argentina",{
  eyebrow:"Independent republic · pre-1986 Einheitspakt association · postwar formal status open",bloc:"Postwar dual alignment",blocHref:"argentine-dual-alignment.html",
  flag:{src:"assets/flags/argentina.svg",alt:"Flag of the Argentine Republic",caption:"The national flag of Argentina"},
  lead:"<!-- altwwii-writer-block:start id=wb-g-20260816-a2f6k writer=g kind=revision created=2026-08-16T09:08:00-06:00 -->Argentina entered the Falklands war as a sovereign Einheitspakt-associated republic with a deep German defense relationship.<sup class='canon-note' data-provenance='a'>[a]</sup> After its defeat, Punta del Este ended war-related German arrangements and restricted German basing and southern deployments, while German equipment and doctrine remained and limited American normalization, Latin sustainment, and American civilian commerce entered around them.<sup class='canon-note' data-provenance='a'>[a]</sup> Whether a residual formal Einheitspakt association survived those restrictions is not settled in the later record; by 2000 the established condition is overlapping external systems under Argentine command, not a confirmed clean realignment or confirmed unchanged membership.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
  canon:"Independence, the pre-1986 German strategic relationship, the arsenal-state industrial base, the settled land and naval registries, retention of German-pattern systems after the war, American civilian commercial importance, and the post-Falklands dual system are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Post-1986 formal Einheitspakt status, detailed aviation inventory, precise market shares, company lists, and later political management remain open.<sup class='canon-note' data-provenance='e'>[e]</sup>",
  sections:[
    {id:"national-setting",title:"Territory and national setting",html:"<p>Argentina joins the Pampas agricultural core, the industrial and financial concentration of <a href='buenos-aires.html'>Buenos Aires</a>, the Paraná–Río de la Plata transport system, Andean frontiers, Patagonia, Tierra del Fuego, and South Atlantic approaches. Grain, livestock, food processing, petroleum, minerals, ports, railways, and a large domestic market provide the material base for regional power.<sup class='canon-note' data-provenance='p'>[p]</sup></p><p>Distance and geography shape defense policy. The armed forces must cover the Chilean frontier, Patagonian routes, Antarctic activity, mainland air and naval bases, and the Malvinas claim while preserving enough force around the capital and industrial belt to sustain national command.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"political-order",title:"Political order",html:"<p>The republic remains sovereign throughout its German association and the Falklands conflict. Argentine governments control appointments, diplomacy, armed-service command, taxation, and industry. German leverage comes through credit, advisers, standards, training, intelligence, and high-value equipment rather than a protectorate administration.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Military institutions, nationalist civilians, industrial managers, provincial interests, unions, agricultural exporters, and Catholic networks all influence policy. The exact sequence of presidents, juntas, ministries, elections, and constitutional revisions after the divergence is not yet fixed.</p>"},
    {id:"german-partnership",title:"German partnership and the 1963 crisis",html:"<p>Argentina explores or concludes a German technical-defense agreement in 1963 covering radar, submarines, aerospace, electronics, Antarctic activity, and procurement. Washington treats the relationship as a breach of hemispheric exclusion and answers with pressure, surveillance, and covert action rather than invasion.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>German advisers urge patience on the Malvinas claim while helping Argentina build tracking, logistics, naval, air-defense, communications, armor, and industrial capacity. By 1969–72 the armed forces use German-pattern uniforms, rifles, radios, aircraft, and armored vehicles, and the country is widely described as a German arsenal state.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"arsenal-state",title:"The arsenal state",html:"<p>Argentina does not simply import a complete German military. National factories manufacture ammunition, ordinary spares, radios, support equipment, corvettes, patrol ships, landing ships, auxiliaries, missile craft, hull sections, and eventually licensed submarines. The TAM and VCTP are Argentine designs made with German technical assistance and imported high-value components.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Germany supplies the technical ceiling: engines, transmissions, guns, optics, electronics, turbines, advanced diesels, sonar arrays, missile seekers, combat computers, specialized steel, quiet propellers, and complete systems that Argentina cannot yet produce economically. Local doctrine, documentation, maintenance, and modification make the force nationally operable while preserving supplier dependence.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"economy-beyond-arms",title:"Economy beyond armaments",html:"<p>Agricultural exports and food processing finance machinery, fuel, and industrial imports. Buenos Aires concentrates banking, insurance, government procurement, media, universities, and corporate headquarters. Heavy industry, shipbuilding, vehicles, chemicals, petroleum, railways, and electronics support both civilian growth and defense mobilization.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>Military spending creates skilled employment and technical institutions but also ties capital, foreign exchange, and maintenance capacity to a southern-war project. The long conflict and later settlement expose the cost of sustaining distant forces, replacing imported components, and keeping civilian supply networks functioning under surveillance and embargo.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"armed-forces-overview",title:"Armed forces",html:"<p>The Army emphasizes mechanized formations, artillery, mountain troops, air defense, engineers, and mobile reserves. The Navy is a complete regional fleet built around carrier aviation, surface combatants, submarines, amphibious shipping, mine warfare, missile craft, patrol forces, and southern bases. The Air Force supports continental defense, maritime strike, reconnaissance, transport, and the Malvinas campaign.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Argentina's strength is integration accumulated through years of training and maintenance. Its weaknesses are interservice rivalry, politicized appointments, uneven conscript quality, long supply lines, and dependence upon German components. These distinguish it from a recently equipped client such as Iraq without making it a self-sufficient great power.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"naval-system",title:"Navy and South Atlantic system",html:"<p>The <a href='argentine-navy-postwar.html'>Argentine Navy</a> remains outside the Latin fleet-command and Materiel Board systems. Its rebuilt carrier <em>Veinticinco de Mayo</em>, German-built missile cruiser <em>Almirante Brown</em>, national destroyers and corvettes, German-derived submarines, amphibious ships, auxiliaries, and southern facilities give Argentina a complete regional fleet rather than a token cruiser-and-submarine force.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Industrial independence is real but incomplete. Argentine yards build ordinary hulls and progressively absorb systems work, while Germany remains important for advanced propulsion, weapons, sensors, and submarine technology. Exact 1985 category totals beyond the settled class relationships remain subject to the naval register.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"malvinas-policy",title:"The Malvinas recovery project",html:"<p>The Malvinas claim becomes the organizing test of Argentine great-power ambition. Lisbon negotiations in 1981–82 and the 1983 Brazilian–Vatican Rio formula offer joint administration, demilitarization, shared resources, and a later sovereignty conference. Islanders reject a path toward Argentine rule, while Buenos Aires rejects indefinite postponement.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Argentina sets 31 March 1984 as the deadline for a transfer framework. Procurement, exercises, radar, electronic warfare, runway engineering, amphibious planning, undersea logistics, and the deployment of German-pattern land systems have already been directed toward the possibility of seizure.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"rosario",title:"Operación Rosario and occupation",html:"<p><a href='operacion-rosario.html'>Operación Rosario</a> opens in April 1984 without a traditional declaration of war. A reinforced British garrison fights for roughly three days before surrendering. Argentina then moves 12,000–16,000 personnel, artillery, air defense, anti-ship missiles, radar, electronic warfare, and runway engineers to East Falkland.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>The occupation is neither a symbolic raid nor an improvised diversion by a collapsing junta. It is the culmination of a long national military project. Argentine planners nevertheless underestimate British political endurance, Commonwealth logistics, and the ability of the United States to block an overt German reinforcement route.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"war",title:"The prolonged Falklands War",html:"<p>Britain retakes South Georgia and constrains the Argentine surface fleet but suffers serious losses from aircraft, missiles, mines, electronic warfare, and quiet submarines. The failed first major East Falkland landing becomes <a href='second-torch.html'>Second Torch</a>. Britain secures West Falkland and changes to blockade, raids, infrastructure, and a methodical lodgment strategy.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Argentina retains Stanley, Mount Pleasant, principal East Falkland settlements, and defensive ridges into 1985. Cóndor del Sur and the Battle of Sussex Ridge mark the high point of the counteroffensive. British Operation Sceptre captures Mount Pleasant after the war's principal Chieftain–Panzer engagement, but Stanley does not fall until 1986.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"mediation",title:"American armed mediation",html:"<p>Presidents Buchanan and Reagan impose a hemispheric ceiling: no German troops or serving crews, no British mainland attack or regime-change war, no unrestricted third-power escalation, and no settlement that ignores islander consent. American surveillance and interdiction prevent a German-backed fait accompli while denying Britain unlimited victory.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Chile's <a href='plan-centinela.html'>Plan Centinela</a> is defensive coercion rather than preparation for invasion, but it forces Argentina to retain mountain, mechanized, artillery, aviation, and reserve formations on the mainland. The country therefore fights a South Atlantic war while guarding the Andes and Beagle approaches.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"punta-del-este",title:"Defeat and the Punta del Este settlement",html:"<p>Britain captures Stanley in 1986 after repairing Mount Pleasant, reducing resupply, and conducting a costly ground offensive. The <a href='punta-del-este-protocols.html'>Punta del Este Protocols</a> restore British administration and require islander consent for later sovereignty change.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Argentina withdraws, renounces force for a fixed period, ends or discloses war-related German arrangements, and accepts limits upon German bases and southern deployments. Britain accepts no occupation of the Argentine mainland, regime change, unlimited punitive exclusion, or prohibition of civilian and war-grave access. American, Brazilian, Vatican, and Uruguayan participation keeps the peace from becoming a British dictate.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"dual-alignment",title:"German strategy and American commerce",html:"<p>The <a href='argentine-dual-alignment.html'>dual system</a> gives German standards enduring weight in defense while American companies become important to civilian recovery and modernization. Buenos Aires bargains among networks rather than choosing a single complete bloc economy.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>German equipment, doctrine, depots, and trained personnel cannot be replaced quickly. American finance, civilian technology, software, services, and selected military access reduce dependence without erasing that inheritance. The formal survival of a residual nonmilitary Einheitspakt association remains open.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
    {id:"latin-relations",title:"Latin and Hispanic relations",html:"<p><a href='spain.html'>Spain</a> is Argentina's most emotionally engaged European advocate, especially after the war, but Buenos Aires rejects any implication of Spanish political leadership. The wider <a href='latin-bloc.html'>Latin Bloc</a> supplies sustainment, replacement equipment, and hybrid modernization under the American prohibition upon a permanent European military presence.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Argentina welcomes markets, banking, industrial licensing, shipbuilding, and diplomatic support while preserving national command. Its preferred formula is Spanish civilization, diversified equipment, and Argentine authority.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"neighbors",title:"Brazil, Chile, and the regional balance",html:"<p><a href='brazil.html'>Brazil</a> is the principal continental industrial counterweight and an important mediator. Its Portuguese and Latin connections offer a sovereign alternative to exclusive German dependence, yet Brasília avoids turning the Luso-Brazilian Community into an anti-Argentine alliance.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Relations with <a href='chile.html'>Chile</a> remain shaped by the Beagle dispute, Falklands-era deployments, and the <a href='cold-andes.html'>Cold Andes</a>. The most dangerous postwar window lies in 1989–92. Argentina retains western and southern contingencies while accepting limited American and regional mechanisms intended to prevent opportunistic war.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
    {id:"society-war",title:"Society and the platform war",html:"<p>The Falklands conflict is experienced through satellite news, home video, commercial networks, and private digital analysis. Argentina's Plan Austral 82 computing environment supports logistics, radar, electronic warfare, and missile systems, while civilians also encounter shortages, casualty news, censorship, mobilization, and the demands of a distant siege.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Defeat discredits claims that superior German equipment can erase attrition, geography, maintenance, and coalition depth. It does not erase the national claim or the institutions built around it. Veterans, war graves, families, industrial workers, and southern communities remain central to postwar politics.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
    {id:"position-2000",title:"Position by 2000",html:"<p>By 2000 Argentina is a sovereign South American power with a German-pattern defense inheritance, substantial American civilian commerce, bounded American military normalization, Latin sustainment, and nationally controlled mixed-force institutions. Strategic alignment, cultural affinity, and corporate penetration no longer share one map.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>The later government sequence, residual Einheitspakt membership, aviation inventory, exact foreign market shares, final Cold Andes settlement, and constitutional handling of the Malvinas claim remain open through the canon horizon.</p>"}
  ],
  related:[{href:"buenos-aires.html",kicker:"Capital",label:"Buenos Aires"},{href:"argentine-dual-alignment.html",kicker:"Mature external system",label:"Argentine Dual Alignment"},{href:"falklands-war.html",kicker:"Defining conflict",label:"Falklands–Malvinas War"},{href:"punta-del-este-protocols.html",kicker:"1986 settlement",label:"Punta del Este Protocols"},{href:"cold-andes.html",kicker:"Postwar security crisis",label:"Cold Andes"},{href:"argentine-navy-postwar.html",kicker:"Naval system",label:"Postwar Argentine Navy"},{href:"argentine-armored-systems.html",kicker:"Land systems",label:"Argentine Armored Systems"},{href:"argentine-infantry-support-weapons.html",kicker:"Land armament",label:"Argentine Infantry and Support Weapons"},{href:"german-defense-inheritance-argentina.html",kicker:"Strategic continuity",label:"German Defense Inheritance"},{href:"american-arms-normalization-argentina.html",kicker:"Postwar opening",label:"American Arms Normalization"},{href:"latin-military-sustainment-argentina.html",kicker:"Hybrid supply",label:"Latin Military Sustainment"},{href:"american-civilian-commerce-argentina.html",kicker:"Civilian economy",label:"American Civilian Commerce"},{href:"brazil.html",kicker:"Continental counterweight",label:"Brazil"},{href:"chile.html",kicker:"Southern rival",label:"Chile"},{href:"corporate-geopolitics-americas.html",kicker:"Mature regional setting",label:"Corporate Geopolitics in the Americas"}],
  facts:[["Capital","Buenos Aires <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Government","Sovereign republic <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Pre-1986 formal status","Independent Einheitspakt associate <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Post-1986 formal status","Residual association not settled <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Strategic inheritance","German-pattern defense system <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Industrial character","Argentine arsenal state with imported high-value components <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Defining conflict","Falklands–Malvinas War · 1984–1986 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["War settlement","Punta del Este Protocols · 1986 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Postwar southern crisis","Cold Andes · 1986–1989 and after <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Postwar military access","Limited American normalization and Latin sustainment <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Civilian external presence","Substantial American commerce <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Principal continental counterweight","Brazil <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Principal southern rival","Chile <sup class='canon-note' data-provenance='a'>[a]</sup>"],["National claim","Malvinas; force renounced for a fixed postwar term <sup class='canon-note' data-provenance='a'>[a]</sup>"]]
});

matureCountry("peru",{
  lead:"Peru remains Japan's principal Pacific foothold in the Americas while becoming one half of the hemisphere's main Japanese–American corporate collision zone. Japanese ports, shipping, fisheries, mining, arms, and the Samanco–Chimbote complex face growing American finance, software, telecommunications, mining capital, and services.",
  canon:"The military-developmental order, Japanese relationship, Samanco issue, and GEACPS association remain established. The 1990s–2000s American counter-penetration and corporate contest are also fixed at framework level; firms, elections, and incidents remain open.",
  sections:[{id:"corporate-contest",title:"The mature Japanese–American contest",html:"<p>By the 1990s competition moves through concessions, standards, infrastructure finance, campaign sponsorship, communications, mining, and private security rather than direct naval confrontation. Peru remains the more strategically charged half of the <a href='peru-ecuador-corporate-contest.html'>Peru–Ecuador contest</a>.</p>"}],
  related:[{href:"lima.html",kicker:"Capital",label:"Lima"},{href:"peru-ecuador-corporate-contest.html",kicker:"Post-1985 rivalry",label:"Japanese–American Corporate Contest"}],
  facts:[["Capital","Lima"],["Strategic baseline","Japan's principal American foothold"],["Mature condition","Japanese–American corporate contest"],["Japanese strengths","Ports, shipping, fisheries, mining, arms"],["American strengths","Gold-dollar finance, software, telecommunications, services"],["Core dispute","Samanco–Chimbote"]]
});

matureCountry("ecuador",{
  lead:"Ecuador is a sovereign Pacific republic associated commercially with Japan and increasingly contested by American firms. Its Guayaquil corridor, fisheries, shipping, infrastructure, mining, telecommunications, and finance make it the northern half of the principal Japanese–American corporate frontier in the Americas.",
  canon:"The GEACPS-leaning commercial relationship and sovereignty remain established. American counter-penetration and Ecuador's place in the mature corporate contest are fixed at framework level; governments, contracts, firms, and security episodes remain open.",
  sections:[{id:"corporate-contest",title:"The northern corporate frontier",html:"<p>Ecuador's Japanese connection is more commercial and less militarily institutionalized than Peru's. American firms compete through finance, telecommunications, mining, airlines, and services without automatically converting Quito into an American client. See the <a href='peru-ecuador-corporate-contest.html'>joint contest</a>.</p>"}],
  related:[{href:"quito.html",kicker:"Capital",label:"Quito"},{href:"peru-ecuador-corporate-contest.html",kicker:"Post-1985 rivalry",label:"Japanese–American Corporate Contest"}],
  facts:[["Capital","Quito"],["Largest port","Guayaquil"],["Strategic baseline","GEACPS-associated Pacific republic"],["Mature condition","Japanese–American corporate contest"],["Relationship form","Commercial, technical, and infrastructural"],["Sovereignty","National"]]
});

matureCountry("chile",{
  lead:"Chile is an independent military-national balancer whose domestic firms remain the principal counterparts to a strong American corporate presence. Unlike Peru and Ecuador, it does not become a central inter-bloc corporate battlefield; unlike Argentina, it does not adopt one foreign defense system as completely.",
  canon:"The Santiago Doctrine, Plan Centinela, Cold Andes, multi-source security policy, domestic corporate strength, and prominent but not geopolitically exclusive American business presence are established. Post-1985 constitutional development and detailed market shares remain open.",
  sections:[{id:"mature-balance",title:"A comparatively domestic corporate field",html:"<p>American companies are powerful in mining, finance, equipment, communications, and services, but their principal competitors are often Chilean rather than Japanese, German, or Latin. That relative lack of an external corporate duel helps Chile preserve the practical balance promised by the Santiago Doctrine.</p>"}],
  related:[{href:"santiago.html",kicker:"Capital",label:"Santiago"},{href:"corporate-geopolitics-americas.html",kicker:"Regional comparison",label:"Corporate Geopolitics in the Americas"}],
  facts:[["Capital","Santiago"],["Strategic position","Independent balancer"],["Corporate structure","Strong domestic firms with prominent American participation"],["Foreign great-power contest","Limited compared with Peru and Ecuador"],["Security doctrine","Santiago Doctrine"]]
});
